class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        m,n=len(obstacleGrid),len(obstacleGrid[0]);dp=[0]*n;dp[0]=1
        for r in range(m):
            for c in range(n):
