class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m,n=len(grid),len(grid[0]);dp=[float('inf')]*n;dp[0]=0
        for r in range(m):
            for c in range(n):dp[c]=grid[r][c]+min(dp[c],dp[c-1] if c>0 else float('inf'))
        return dp[-1]

class Solution {
    public int minPathSum(int[][] grid) {
        int n=grid[0].length;int[] dp=new int[n];Arrays.fill(dp,Integer.MAX_VALUE);dp[0]=0;
        for(int[] row:grid)for(int c=0;c<n;c++){int left=c>0?dp[c-1]:Integer.MAX_VALUE;dp[c]=row[c]+Math.min(dp[c],left);}
        return dp[n-1];
    }
}

