class Solution:
    def plusOne(self, digits: List[int]) -> List[int]:
        for i in range(len(digits)-1,-1,-1):
            if digits[i]<9:digits[i]+=1;return digits
            digits[i]=0
        return [1]+digits

class Solution {
    public int[] plusOne(int[] digits) {
        for(int i=digits.length-1;i>=0;i--){if(digits[i]<9){digits[i]++;return digits;}digits[i]=0;}
        int[] out=new int[digits.length+1];out[0]=1;return out;
    }
}

class Solution:
    def addBinary(self, a: str, b: str) -> str:
        i,j=len(a)-1,len(b)-1;carry=0;out=[]
        while i>=0 or j>=0 or carry:
            total=carry
            if i>=0:total+=int(a[i]);i-=1
            if j>=0:total+=int(b[j]);j-=1
            out.append(str(total%2));carry=total//2
        return ''.join(reversed(out))

class Solution {
    public String addBinary(String a,String b) {
        int i=a.length()-1,j=b.length()-1,carry=0;StringBuilder out=new StringBuilder();
        while(i>=0||j>=0||carry!=0){int total=carry;if(i>=0)total+=a.charAt(i--)-'0';if(j>=0)total+=b.charAt(j--)-'0';out.append((char)('0'+total%2));carry=total/2;}
        return out.reverse().toString();
    }
}

