class Solution:
    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:
        out=[];i=0
        while i<len(words):
            j=i+1;letters=len(words[i])
            while j<len(words) and letters+len(words[j])+(j-i)<=maxWidth:letters+=len(words[j]);j+=1
            gaps=j-i-1
            if j==len(words) or gaps==0:
                line=' '.join(words[i:j]);line+= ' '*(maxWidth-len(line))
            else:
                spaces=(maxWidth-letters)//gaps;extra=(maxWidth-letters)%gaps;parts=[]
                for k in range(i,j-1):parts.append(words[k]+' '*(spaces+(1 if k-i<extra else 0)))
                parts.append(words[j-1]);line=''.join(parts)
            out.append(line);i=j
        return out

import java.util.*;

class Solution {
    public List<String> fullJustify(String[] words,int maxWidth) {
        List<String> out=new ArrayList<>();int i=0;
        while(i<words.length){int j=i+1,letters=words[i].length();while(j<words.length&&letters+words[j].length()+(j-i)<=maxWidth){letters+=words[j].length();j++;}
            int gaps=j-i-1;StringBuilder line=new StringBuilder();
            if(j==words.length||gaps==0){for(int k=i;k<j;k++){if(k>i)line.append(' ');line.append(words[k]);}while(line.length()<maxWidth)line.append(' ');}
            else{int spaces=(maxWidth-letters)/gaps,extra=(maxWidth-letters)%gaps;for(int k=i;k<j-1;k++){line.append(words[k]);for(int z=0;z<spaces+(k-i<extra?1:0);z++)line.append(' ');}line.append(words[j-1]);}
            out.add(line.toString());i=j;
        }
        return out;
    }
}

class Solution:
    def mySqrt(self, x: int) -> int:
        left,right=0,x+1
        while left+1<right:
            mid=(left+right)//2
            if mid<=x//mid:left=mid
            else:right=mid
        return left

class Solution {
    public int mySqrt(int x) {
        long left=0,right=(long)x+1;
        while(left+1<right){long mid=left+(right-left)/2;if(mid==0||mid<=x/mid)left=mid;else right=mid;}
        return (int)left;
    }
}

class Solution:
    def climbStairs(self, n: int) -> int:
        a,b=1,1
        for _ in range(n-1):a,b=b,a+b
        return b

class Solution {
    public int climbStairs(int n) { int a=1,b=1;for(int i=1;i<n;i++){int t=a+b;a=b;b=t;}return b; }
